mapper.update:
UPDATE users
SET user_last_login_at = #{lastLoginAt}
WHERE user_num = #{userNum}

UPDATE users
SET login_fail_count = 0, locked_until = NULL
WHERE user_num = #{userNum}

UPDATE users
SET login_fail_count = login_fail_count + 1
WHERE user_num = #{userNum}

UPDATE users
SET locked_until = #{lockedUntil}
WHERE user_num = #{userNum}
  AND login_fail_count >= #{maxFailCount}

UPDATE users
SET user_nickname = #{nickname}
WHERE user_num = #{userNum}
  AND user_status = 'A'

UPDATE users
SET user_pw = #{encodedPassword}
WHERE user_num = #{userNum}
  AND user_status = 'A'

UPDATE users
SET user_pw = #{encodedPassword}, login_fail_count = 0, locked_until = NULL
WHERE user_num = #{userNum}

UPDATE users
SET user_status = 'W', user_withdrawn_at = #{withdrawnAt}
WHERE user_num = #{userNum}
  AND user_status = 'A'

mapper.select:
SELECT user_num
FROM users
WHERE user_num = #{userNum}
  AND user_withdrawn_at < #{purgeBefore}
  AND user_status = 'W'
FOR UPDATE

mapper.delete:
